{
  "description": "The creature is a standing chimera that combines a fox and an owl, shown in right-facing profile on a small patch of light sandy ground against a plain background. The upper head, hindquarters, hind legs and long tail are those of a reddish-orange fox with dense fur, while the neck, chest, back and paired folded wings are covered in the pale, speckled plumage of a barn owl. It stands upright on two hind legs with its wings folded close to its sides and its long bushy tail extended straight out behind it, nearly touching the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a fox head with a narrow pointed muzzle, black nose, amber-brown eyes, white fur on the muzzle, chin and throat, and reddish-orange fur on the forehead, cheeks and sides, with fine whiskers on the muzzle",
      "where": "at the top front of the body, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two large upright pointed ears with reddish-orange outer fur, pale cream inner fur and dark brown-black rims and interiors",
      "where": "on top of the head, one slightly in front of the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in reddish-brown fox fur that is lighter cream on the inner thigh and belly, bent at the hock in a digitigrade stance",
      "where": "under the lower torso, extending down to the ground"
    },
    {
      "part": "feet",
      "looks_like": "two dark brown-black paws with visible toe pads and short curved claws",
      "where": "at the ends of the hind legs resting on the sandy ground"
    },
    {
      "part": "tail",
      "looks_like": "one long, thick, very bushy tail covered in long reddish-brown fur with a white-cream tip",
      "where": "extending backward from the rear of the body, trailing horizontally just above the ground"
    },
    {
      "part": "wings",
      "looks_like": "two folded wings with layered flight feathers patterned in tan, light brown, grey and cream with dark speckles and dark barring on the primaries",
      "where": "on the left and right sides of the mid-torso, folded against the body"
    },
    {
      "part": "feathers",
      "looks_like": "dense owl-like plumage; white with small black spots on the chest and underside, mottled tan, buff and grey on the back and wing coverts, and barred tan and cream on the flight feathers and lower wing edges",
      "where": "covering the throat, chest, belly, back and wings"
    },
    {
      "part": "markings",
      "looks_like": "small scattered black and dark brown spots on the white chest and throat, and mottled grey-brown scalloped patterning on the back and upper wings",
      "where": "across the front of the neck, chest, belly and dorsal wing surfaces"
    }
  ],
  "attached_objects": [],
  "animals": ["fox", "barn owl"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
